21	  const nonComponents = items.filter(
22	    (item) => !COMPONENT_TYPES.includes(item.type),
23	  );
24	  let total = sumOfItemPrices(nonComponents);
25	  for (const type of COMPONENT_TYPES) {
26	    const count = items.filter((item) => item.type === type).length;
27	    if (count === COMPONENT_BLOCK_SIZE) {
28	      total += COMPONENT_BLOCK_PRICE;
29	    } else {
30	      total += count * priceList[type];
31	    }
32	  }
33	  return total;
34	};
35	
36	const PROCESSING_FEE = 5;
37	
38	type QuoteStep = { op: "quote"; items: Item[] };
39	type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
40	
41	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
42	  const results = scenario.steps.map((step) => ({
43	    premium: basePremium(step.items) + PROCESSING_FEE,
44	  }));
45	  return { results };
46	};
